# Testing code generated by chatgpt: Nov 26, 2026

import sys
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(PROJECT_ROOT))

import time
import numpy as np
import matplotlib.pyplot as plt
from shapely import Polygon

from config.config import CONFIG
from geometry.convert_to_simulation_grid import convert_to_simulation_grid
from optics.aerial_image import compute_aerial_image
from geometry.mask_definition import mask_definition
from optimization.ga.optimizer import GeneticAlgorithmOptimizer
from optimization.ga.fitness import fitness

PX_PER_UM = CONFIG["optics"]["grid_resolution_px_per_um"]
WINDOW_SIZE = CONFIG["optics"]["window_size_xy"]
MAX_GEN = CONFIG["optimization"]["max_generations"]
POPULATION_SIZE = CONFIG["optimization"]["population_size"]
EXPECTED_CHILDREN = CONFIG["optimization"]["children_from_crossover"]


start_total = time.perf_counter()

polygons = mask_definition()

output_grid = convert_to_simulation_grid(
    polygons = polygons,
    grid_resolution_px_per_um = PX_PER_UM
)

fft_output_grid = compute_aerial_image(output_grid)


# THRESHOLD PICKED TO MIMIC EXPECTED RESULTS LIKE OVER FITTING IN THE INSIDE EDGE.
# over fitting in the inside edge happens due to 90 degree turn
threshold = CONFIG["printing"]["default_intensity_threshold"]

developed_mask = fft_output_grid >= threshold

fig, ax = plt.subplots(figsize=(8, 6))
im = ax.imshow(developed_mask, cmap='Blues')
ax.set_xlabel(f'X (pixels) / ({1000/PX_PER_UM:.2f} nm per pixel)')
ax.set_ylabel(f'Y (pixels) / ({1000/PX_PER_UM:.2f} nm per pixel)')

# printing desired mask outline
um_to_pixel = 1.0 / PX_PER_UM
for poly_points, _ in polygons:
    pixels = (np.array(poly_points) * PX_PER_UM).tolist()
    poly = Polygon(pixels)
    ax.plot(poly.exterior.xy[0], poly.exterior.xy[1], 'k-', linewidth=4, linestyle='solid')

ax.set_title('fft')
step = 16
ax.set_xticks(range(0, WINDOW_SIZE, step))
ax.set_yticks(range(0, WINDOW_SIZE, step))


end_total = time.perf_counter()

print(end_total - start_total)

plt.tight_layout()
#plt.show()

ga = GeneticAlgorithmOptimizer(
    population_size = POPULATION_SIZE,
    max_generations = MAX_GEN,
    seed=CONFIG["experiment"]["random_seed"],
    expected_children = EXPECTED_CHILDREN
)

best_mask = ga.optimize(
    target_mask = output_grid,
    initial_mask = output_grid
)

best_aerial_image = compute_aerial_image(best_mask)

initial_developed_mask = fft_output_grid >= threshold
optimized_developed_mask = best_aerial_image >= threshold

fig, ax = plt.subplots(1, 2, figsize=(14, 6))

ax[0].imshow(initial_developed_mask, cmap="Blues")

for poly_points, _ in polygons:
    pixels = (np.array(poly_points) * PX_PER_UM).tolist()
    poly = Polygon(pixels)
    ax[0].plot(poly.exterior.xy[0], poly.exterior.xy[1], "k-", linewidth=2)

ax[0].set_title("Initial Mask: Developed Resist")
ax[0].set_xlabel(f"X (pixels) / ({1000/PX_PER_UM:.2f} nm per pixel)")
ax[0].set_ylabel(f"Y (pixels) / ({1000/PX_PER_UM:.2f} nm per pixel)")

ax[1].imshow(optimized_developed_mask, cmap="Blues")

ax[1].contour(
    best_mask,
    levels=[0.5],
    colors="black",
    linewidths=2
)

ax[1].set_title("Optimized Mask: Developed Resist")
ax[1].set_xlabel(f"X (pixels) / ({1000/PX_PER_UM:.2f} nm per pixel)")
ax[1].set_ylabel(f"Y (pixels) / ({1000/PX_PER_UM:.2f} nm per pixel)")

for axis in ax:
    axis.set_xticks(range(0, WINDOW_SIZE, step))
    axis.set_yticks(range(0, WINDOW_SIZE, step))

plt.tight_layout()

plt.savefig(PROJECT_ROOT / "mask_comparison.png", dpi=300)

plt.imsave(
    PROJECT_ROOT / "optimized_mask.png",
    best_mask,
    cmap="gray",
    vmin=0,
    vmax=1
)

plt.show()